INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_ehs_202605','oa_ehs_zhejiang','May bulletin on typical machinery injury cases','All three accidents occurred in lanes where forklifts and pedestrians shared the same traffic route; the notice requires all visitors to the plant to use physically segregated pedestrian walkways.','https://ehs.example.invalid/2026/05','2026-05-28T01:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_ehs_noise','oa_ehs_zhejiang','Key occupational protection points for high-decibel noise in the stamping workshop','Continuous exposure exceeding eighty-five decibels requires mandatory provision of earplugs or earmuffs; short visits are recommended to be limited to no more than forty minutes.','https://ehs.example.invalid/noise','2026-06-09T01:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_ehs_dust','oa_ehs_zhejiang','Visitor Protection for Grinding and Dust-Generating Work Areas','Non-operational personnel are not advised to remain at workstations with high dust concentrations; if passage is necessary, a particulate respirator must be worn.','https://ehs.example.invalid/dust','2026-06-22T01:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_scm_freight','oa_scm_weekly','June Yangtze River Delta road freight rates edged up','The full-vehicle freight rate on the Hu-Hang-Yong route rose 4% month on month, and collection of the fuel surcharge has resumed.','https://scm.example.invalid/freight-0612','2026-06-12T00:30:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_scm_capacity','oa_scm_weekly','Jiaxing Injection Molding Capacity: Q3 Production Scheduling Is Tight','The top three factories are fully booked for July production, and lead times for new orders are generally delayed by ten to fourteen days.','https://scm.example.invalid/capacity-q3','2026-06-19T00:30:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_hr_volunteer','oa_hr_center','Reaffirmation of the principle that participation in team activities is voluntary','Team activities organized by each department must not be linked to attendance or performance evaluations. Members may withdraw at any time without giving a reason.','https://hr.example.invalid/volunteer','2026-06-03T03:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_hr_privacy','oa_hr_center','Guidelines for minimizing the collection of employees'' personal information','When providing personnel information externally, aggregate it by headcount and category; do not disclose names together with health, family, or identification document information.','https://hr.example.invalid/privacy','2026-06-16T03:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_fin_invoice','oa_finance_hub','Invoice requirements for event-related expenses','Chartered vehicles, catering, and insurance must have VAT invoices bearing the company name; invoices in an individual''s name and receipts will not be reimbursed under any circumstances.','https://fin.example.invalid/invoice','2026-05-21T06:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_fin_payee','oa_finance_hub','Standards for verifying recipients of corporate payments','The recipient account name must match the contracting entity exactly. If a personal or temporary account appears, payment should be suspended and the matter verified through the contractual channel.','https://fin.example.invalid/payee','2026-06-24T06:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_admin_bus','oa_admin_service','Vehicle service and in-vehicle reminder template','Vehicle requests for more than 30 people must be submitted five business days in advance; driver qualifications and vehicle insurance will be centrally reviewed by Administration.','https://admin.example.invalid/bus','2026-06-05T07:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_park_visitor','oa_jiaxing_park','Management of visitor access and photography in the industrial park','Enterprises within the industrial park may set their own photography boundaries. Group visitors must register at the gate and wear visitor badges throughout the visit.','https://park.example.invalid/visitor','2026-06-11T05:00:00Z');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES ('post_park_road','oa_jiaxing_park','Nanhu Avenue July Road Renovation Notice','The eastern section of the industrial park will be constructed in stages; large buses are advised to detour via Huayuan Road to enter the park through the north gate.','https://park.example.invalid/road-july','2026-06-27T05:00:00Z');
